'use strict';
const account={ready:false,user:null,guest:false,mode:'login',message:'',busy:false,revision:0,syncing:false,dirty:false,conflict:false,available:false,profileMessage:'',timer:null};
const guestKey=KEY,guestState=structuredClone(state);let localEpoch=0;
const baseRender=render;
navs.push(['account','☺','个人档案']);
function accountCacheKey(){return 'shijie-account-v1:'+account.user.id}
async function api(path,options={}){const headers={'X-Shijie-Request':'1',...(options.body?{'Content-Type':'application/json'}:{})};const r=await fetch(path,{...options,credentials:'same-origin',headers:{...headers,...options.headers}});let data;try{data=await r.json()}catch{throw Object.assign(Error('账户服务暂时不可用。'),{status:r.status})}if(!r.ok)throw Object.assign(Error(data.error||'请求未完成。'),{status:r.status});return data}
function statusText(){return account.conflict?'存在同步冲突':account.syncing?'正在同步':account.dirty?'待同步':account.user?'已保存到账户':'访客 · 本机记录'}
function chip(){window.CET6_ACCOUNT_MODE=!!account.user;const aside=document.querySelector('.aside-bottom');if(aside)aside.innerHTML=account.user?'● 账户记录 · 自动同步<small>每次积累，都有迹可循。</small>':'● 访客记录 · 浏览器保存<small>登录后可建立个人学习档案。</small>';let el=document.getElementById('account-chip');if(!el){el=document.createElement('div');el.id='account-chip';el.className='account-chip';document.querySelector('header').appendChild(el)}el.innerHTML=`<a href="#account">${esc(account.user?account.user.nickname:'登录 / 注册')}</a> <span class="sync-status">${esc(statusText())}</span>`}
function loginUI(){return `<div class="auth-layout"><section class="auth-intro"><span class="badge">拾阶 · PERSONAL STUDY SPACE</span><h1>你的积累，<br>值得好好保存。</h1><p>单词、练习、草稿与复盘，<br>在属于你的学习档案里继续。</p><div class="auth-features"><span>363 个词汇 · 四种练法</span><span>50 套专题阅读 · 答案解析</span><span>写作与翻译各 100 套</span></div></section><section class="panel auth-form"><div class="toolbar"><button class="pill ${account.mode==='login'?'active':''}" data-authmode="login">登录</button><button class="pill ${account.mode==='register'?'active':''}" data-authmode="register">注册新账户</button></div><h2>${account.mode==='register'?'从这里，开始你的学习档案':'欢迎回来，继续向前。'}</h2><p class="note">${account.available?'使用邮箱和密码登录，学习记录按账户保存。':'账户服务暂时不可用。可以先使用访客模式。'}</p>${account.message?`<div class="feedback wrong" role="alert">${esc(account.message)}</div>`:''}<form id="account-form">${account.mode==='register'?'<label for="register-nickname">昵称</label><input id="register-nickname" name="nickname" maxlength="40" autocomplete="nickname" required placeholder="怎么称呼你？">':''}<label for="login-email">邮箱</label><input id="login-email" name="email" type="email" autocomplete="username" required maxlength="254" placeholder="you@example.com"><label for="login-password">密码</label><input id="login-password" name="password" type="password" autocomplete="${account.mode==='register'?'new-password':'current-password'}" minlength="12" maxlength="128" required placeholder="12–128 个字符">${account.mode==='register'?'<label for="confirm-password">确认密码</label><input id="confirm-password" type="password" autocomplete="new-password" minlength="12" maxlength="128" required placeholder="再输入一次密码"><p class="note">邮箱用作登录名。本版暂未接入邮件验证或自助密码找回。</p>':''}<button class="btn primary" type="submit" ${account.busy||!account.available?'disabled':''}>${account.busy?'正在处理…':account.mode==='register'?'创建账户并开始学习':'登录并继续学习'}</button></form><div class="toolbar"><button class="btn" data-authaction="guest">先用访客模式</button>${!account.available?'<button class="btn" data-authaction="retry">重试账户服务</button>':''}</div><p class="note">${location.hostname==='127.0.0.1'||location.hostname==='localhost'?'当前为本机服务：账户与记录保存在这台电脑的数据库中。部署到在线服务器后，才可跨设备访问。':'账户记录由网站服务器保存，访客模式仍仅使用浏览器存储。'}</p><p class="note">写译 AI 自动批改尚未启用；当前提供参考与基础规则自查。</p></section></div>`}
function accountUI(){if(!account.user)return loginUI();const u=account.user;return heading('个人学习档案','YOUR LEARNING, YOUR PACE','管理昵称、备考目标和学习记录；各账户独立保存。')+`<div class="grid"><section class="panel"><span class="badge">${esc(u.email)}</span><h2 style="margin-top:18px">${esc(u.nickname)}，保持自己的节奏。</h2><form id="profile-form" class="profile-form"><label for="profile-nickname">昵称</label><input id="profile-nickname" value="${esc(u.nickname)}" maxlength="40" required><label for="profile-exam">目标考试日期（可选）</label><input id="profile-exam" type="date" value="${esc(u.examDate)}"><label for="profile-words">每日词汇目标</label><input id="profile-words" type="number" min="1" max="100" step="1" value="${u.dailyWords}" required><label for="profile-minutes">每日学习时间目标（分钟）</label><input id="profile-minutes" type="number" min="5" max="240" step="1" value="${u.dailyMinutes}" required><button class="btn primary" type="submit" ${account.busy?'disabled':''}>保存个人资料</button></form>${account.profileMessage?`<div class="feedback" role="status">${esc(account.profileMessage)}</div>`:''}</section><section class="panel" style="align-self:start"><h2>学习记录同步</h2><p class="note" id="sync-detail">${esc(statusText())} · 版本 ${account.revision}</p>${account.conflict?'<div class="feedback wrong">另一处已更新记录。请选择保留哪一份，当前内容不会自动覆盖服务器。</div><div class="toolbar"><button class="btn" data-authaction="use-server">备份本机后读取服务器</button><button class="btn" data-authaction="keep-local">备份服务器后保留本机</button></div>':'<button class="btn" data-authaction="sync">立即同步</button>'}<p class="note">${location.hostname==='127.0.0.1'?'当前记录保存在本机服务数据库，尚未部署到公网。':'重新登录可读取服务器保存的学习进度。'}</p><div class="toolbar"><button class="btn" data-authaction="import-guest">将访客记录导入此账户</button><button class="btn" data-authaction="logout">同步并退出登录</button></div><div id="guest-import-confirm"></div><p class="note">导入访客记录需再次确认，并会先发起当前账户记录的备份下载。退出后会回到访客空间，账户数据不会变成访客记录。</p></section></div>`}
render=function(){if(!account.ready){$('#app').innerHTML='<section class="panel empty">正在连接个人学习档案…</section>';return}if(!account.user&&(!account.guest||page==='account')){$('#app').innerHTML=loginUI();$('#breadcrumb').textContent='登录与注册';document.querySelector('nav').innerHTML='<a class="active" href="#account">☺ 登录与注册</a>';chip();return}if(page==='account'){document.querySelector('nav').innerHTML=navs.map(([k,i,t])=>`<a href="#${k}" ${k===page?'class="active"':''}><span class="ico" aria-hidden="true">${i}</span>${t}</a>`).join('');$('#breadcrumb').textContent='个人档案';$('#app').innerHTML=accountUI()}else baseRender();if(account.user&&$('#save-status'))$('#save-status').textContent='本机缓存 · 自动同步到账户';chip()};
save=function(){try{if(account.user){localEpoch++;account.dirty=true;localStorage.setItem(accountCacheKey(),JSON.stringify({state,revision:account.revision,dirty:true}));clearTimeout(account.timer);if(!account.conflict)account.timer=setTimeout(()=>syncAccount(),1200)}else localStorage.setItem(guestKey,JSON.stringify(state));storageOK=true;chip();return true}catch{storageOK=false;toast('浏览器缓存保存失败，请导出备份。');return false}};
async function setUser(user,goHome=true){clearTimeout(account.timer);account.user=user;account.guest=false;account.conflict=false;account.dirty=false;window.CET6_DAILY_GOAL=user.dailyWords;const remote=await api('/api/state');let cache=null;try{cache=JSON.parse(localStorage.getItem(accountCacheKey())||'null')}catch{}account.revision=remote.revision;if(cache?.dirty&&validState(cache.state)){state=cache.state;account.dirty=true;account.conflict=cache.revision!==remote.revision}else{state=remote.state&&validState(remote.state)?remote.state:fresh();state.vocabPractice??={};state.wordSeen??=[];localStorage.setItem(accountCacheKey(),JSON.stringify({state,revision:account.revision,dirty:false}))}if(account.dirty&&!account.conflict)account.timer=setTimeout(()=>syncAccount(),500);if(goHome){page='home';location.hash='home'}else{page=location.hash.slice(1);if(!navs.some(n=>n[0]===page))page='home'}render()}
async function syncAccount(){if(!account.user||account.syncing||account.conflict||!account.dirty)return;const userId=account.user.id,epoch=localEpoch;account.syncing=true;chip();try{const out=await api('/api/state',{method:'PUT',body:JSON.stringify({state,revision:account.revision})});if(account.user?.id!==userId)return;account.revision=out.revision;account.dirty=epoch!==localEpoch;localStorage.setItem(accountCacheKey(),JSON.stringify({state,revision:account.revision,dirty:account.dirty}));account.message=''}catch(e){if(e.status===409)account.conflict=true;if(e.status===401)account.message='会话已失效，本机草稿已保留，请重新登录。';else account.message=e.message;toast(account.message)}finally{account.syncing=false;chip();if(page==='account')render();if(account.dirty&&!account.conflict&&!account.message)account.timer=setTimeout(()=>syncAccount(),500)}}
async function initAccount(){if(location.protocol==='file:'){account.ready=true;account.available=false;account.guest=true;render();return}try{const health=await api('/api/health');account.available=!!health.accounts;if(!account.available)throw Error('账户服务未配置。');const out=await api('/api/auth/me');account.ready=true;if(out.user)await setUser(out.user,false);else render()}catch(e){account.ready=true;account.available=false;account.message='无法连接账户服务。登录功能需要运行网站服务端；你仍可使用访客练习。';render()}}
function downloadObject(obj,name){const url=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
document.addEventListener('submit',async e=>{if(e.target.id==='account-form'){e.preventDefault();if(account.busy)return;const email=$('#login-email').value,password=$('#login-password').value,nickname=$('#register-nickname')?.value;if(account.mode==='register'&&password!==$('#confirm-password').value){account.message='两次输入的密码不一致。';render();return}account.busy=true;const submit=e.target.querySelector('button[type=submit]');submit.disabled=true;submit.textContent='正在处理…';try{const out=await api('/api/auth/'+account.mode,{method:'POST',body:JSON.stringify({email,password,nickname})});account.message='';await setUser(out.user);toast('已登录，学习档案已加载。')}catch(err){account.message=err.message;render()}finally{account.busy=false;if(page==='account'||!account.user)render()}}if(e.target.id==='profile-form'){e.preventDefault();if(account.busy)return;const payload={nickname:$('#profile-nickname').value,examDate:$('#profile-exam').value,dailyWords:Number($('#profile-words').value),dailyMinutes:Number($('#profile-minutes').value)};account.busy=true;try{const out=await api('/api/profile',{method:'PUT',body:JSON.stringify(payload)});account.user=out.user;window.CET6_DAILY_GOAL=out.user.dailyWords;account.profileMessage='个人资料已保存。'}catch(err){account.profileMessage=err.message}finally{account.busy=false;render()}}});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.authmode){account.mode=b.dataset.authmode;account.message='';render();return}const a=b.dataset.authaction;if(!a)return;if(a==='guest'){account.guest=true;page='home';location.hash='home';render();return}if(a==='retry'){account.ready=false;render();await initAccount();return}if(a==='sync'){await syncAccount();toast(account.dirty?'记录尚未同步，请检查连接或处理冲突。':'账户记录已同步。');return}if(a==='logout'){await syncAccount();if(account.dirty||account.conflict){toast('请先完成同步或处理冲突，再退出；记录仍保存在当前设备。');return}try{await api('/api/auth/logout',{method:'POST',body:'{}'});account.user=null;account.mode='login';account.revision=0;account.guest=false;window.CET6_DAILY_GOAL=5;state=JSON.parse(localStorage.getItem(guestKey)||'null')||structuredClone(guestState);page='home';location.hash='home';render()}catch(err){toast(err.message)}return}if(a==='import-guest'){$('#guest-import-confirm').innerHTML='<div class="feedback wrong">将用此浏览器的访客记录替换当前账户学习记录。确认前会发起当前账户备份下载。<div class="toolbar"><button class="btn primary" data-authaction="confirm-guest">备份并确认导入</button><button class="btn" data-authaction="cancel-guest">取消</button></div></div>';return}if(a==='cancel-guest'){$('#guest-import-confirm').innerHTML='';return}if(a==='confirm-guest'){let candidate=JSON.parse(localStorage.getItem(guestKey)||'null')||guestState;if(!validState(candidate))return toast('访客记录格式不正确，未导入。');downloadState();state=structuredClone(candidate);save();render();toast('访客记录已导入，等待同步。');return}if(a==='use-server'||a==='keep-local'){try{const remote=await api('/api/state');if(a==='use-server'){downloadState();state=remote.state&&validState(remote.state)?remote.state:fresh();account.revision=remote.revision;account.conflict=false;account.dirty=false;localStorage.setItem(accountCacheKey(),JSON.stringify({state,revision:account.revision,dirty:false}));render();toast('已读取服务器记录。')}else{downloadObject(remote.state||fresh(),'拾阶服务器记录备份.json');account.revision=remote.revision;account.conflict=false;save();await syncAccount();render()}}catch(err){toast(err.message)}}});
window.addEventListener('online',()=>{if(account.user)syncAccount()});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'&&account.user&&account.dirty)syncAccount()});
initAccount();

